SELECT operate_log.id, title, business_type, `method`, request_method, operator_type, operator_name, operator_url, operator_ip, operator_location, operator_param, operator_browser, operator_os, create_time, json_result, status, error_msg, cost_time FROM (SELECT id FROM operate_log
AND title LIKE CONCAT('%',#{queryParams.title},'%')
AND business_type = #{queryParams.businessType}
AND `method` LIKE CONCAT('%',#{queryParams.method},'%')
AND operator_type = #{queryParams.operatorType}
AND operator_name LIKE CONCAT('%',#{queryParams.operatorName},'%')
AND operator_ip = #{queryParams.operatorIp}
AND operator_url LIKE CONCAT('%',#{queryParams.operatorUrl},'%')
AND status = #{queryParams.status}
AND cost_time >= #{queryParams.costTime}
AND create_time >= #{queryParams.startTime}
AND create_time <= #{queryParams.endTime}
ORDER BY create_time DESC
LIMIT #{offset},#{queryParams.pageSize}) subquery LEFT JOIN operate_log ON subquery.id = operate_log.id

